// Process API JSON response
const items = $input.all();
const products = [];

for (const item of items) {
  const data = item.json;

  // Handle Salla API response format
  const productList = data.data?.products || data.products || data.data || [];

  if (Array.isArray(productList)) {
    for (const product of productList) {
      products.push({
        name: product.name || product.title || 'N/A',
        brand: product.brand?.name || product.brand || 'N/A',
        category: product.category?.name || product.category || 'N/A',
        original_price: product.regular_price?.amount || product.price?.regular || product.compare_at_price || 'N/A',
        sale_price: product.sale_price?.amount || product.price?.sale || product.price?.amount || 'N/A',
        discount_percentage: product.discount?.percentage || product.discount_percent || calculateDiscount(product),
        currency: product.currency || product.price?.currency || 'SAR',
        image: product.image?.url || product.thumbnail || '',
        url: product.url || product.link || '',
        in_stock: product.availability || product.in_stock || true,
        sku: product.sku || product.id || ''
      });
    }
  }
}

function calculateDiscount(product) {
  const original = parseFloat(product.regular_price?.amount || product.compare_at_price || 0);
  const sale = parseFloat(product.sale_price?.amount || product.price?.amount || 0);
  if (original > 0 && sale > 0 && original > sale) {
    return Math.round(((original - sale) / original) * 100) + '%';
  }
  return 'N/A';
}

if (products.length === 0) {
  return [{ json: { message: 'No products found in API response', raw_data: items[0]?.json } }];
}

return products.map(p => ({ json: p }));

// Process HTML-extracted product data
const input = $input.first().json;
const products = [];

const names = input.product_names || [];
const originalPrices = input.original_prices || [];
const salePrices = input.sale_prices || [];
const discounts = input.discount_badges || [];
const images = input.product_images || [];
const links = input.product_links || [];

const maxLen = Math.max(names.length, salePrices.length);

for (let i = 0; i < maxLen; i++) {
  const name = names[i] || 'N/A';
  const originalPrice = originalPrices[i] || 'N/A';
  const salePrice = salePrices[i] || 'N/A';
  const discount = discounts[i] || calculateDiscount(originalPrice, salePrice);
  const image = images[i] || '';
  const link = links[i] ? `https://daralamirat.com.sa${links[i]}` : '';

  // Clean price strings
  const cleanPrice = (p) => p.toString().replace(/[^\d.]/g, '');

  products.push({
    name: name.trim(),
    original_price: originalPrice.toString().trim(),
    sale_price: salePrice.toString().trim(),
    discount_percentage: discount.toString().trim(),
    image: image,
    url: link,
    currency: 'SAR',
    scraped_at: new Date().toISOString()
  });
}

function calculateDiscount(original, sale) {
  const o = parseFloat(original.toString().replace(/[^\d.]/g, ''));
  const s = parseFloat(sale.toString().replace(/[^\d.]/g, ''));
  if (o > 0 && s > 0 && o > s) {
    return Math.round(((o - s) / o) * 100) + '%';
  }
  return 'N/A';
}

if (products.length === 0) {
  return [{ json: { message: 'No products extracted from HTML. The page may require JavaScript rendering. Try using a headless browser or the Salla API.', raw_html_length: (input.data || '').length } }];
}

return products.map(p => ({ json: p }));

// Deduplicate and clean final product list
const items = $input.all();
const seen = new Set();
const products = [];

for (const item of items) {
  const p = item.json;

  // Skip error messages
  if (p.message && !p.name) continue;

  const key = (p.name || '').toLowerCase().trim();
  if (key && key !== 'n/a' && !seen.has(key)) {
    seen.add(key);
    products.push({
      name: p.name,
      brand: p.brand || 'N/A',
      category: p.category || 'N/A',
      original_price: p.original_price,
      sale_price: p.sale_price,
      discount_percentage: p.discount_percentage,
      currency: p.currency || 'SAR',
      url: p.url || '',
      image: p.image || '',
      in_stock: p.in_stock !== undefined ? p.in_stock : true,
      scraped_at: new Date().toISOString()
    });
  }
}

if (products.length === 0) {
  return [{
    json: {
      status: 'no_products_found',
      message: 'Could not extract products. The site may be blocking automated access.',
      suggestion: 'Try using Salla API with store credentials, or use a headless browser approach.',
      timestamp: new Date().toISOString()
    }
  }];
}

return products.map(p => ({ json: p }));

// Generate summary report
const items = $input.all();
const products = items.filter(i => i.json.name);

const summary = {
  total_products: products.length,
  scraped_at: new Date().toISOString(),
  source: 'daralamirat.com.sa',
  categories: {},
  price_ranges: {
    min_sale_price: Infinity,
    max_sale_price: 0,
    max_discount: '0%'
  }
};

let maxDiscount = 0;

for (const item of products) {
  const p = item.json;

  // Count categories
  const cat = p.category || 'Uncategorized';
  summary.categories[cat] = (summary.categories[cat] || 0) + 1;

  // Track price ranges
  const salePrice = parseFloat(p.sale_price?.toString().replace(/[^\d.]/g, '') || '0');
  if (salePrice > 0) {
    summary.price_ranges.min_sale_price = Math.min(summary.price_ranges.min_sale_price, salePrice);
    summary.price_ranges.max_sale_price = Math.max(summary.price_ranges.max_sale_price, salePrice);
  }

  const discount = parseInt(p.discount_percentage?.toString().replace(/[^\d]/g, '') || '0');
  if (discount > maxDiscount) {
    maxDiscount = discount;
    summary.price_ranges.max_discount = discount + '%';
  }
}

if (summary.price_ranges.min_sale_price === Infinity) {
  summary.price_ranges.min_sale_price = 'N/A';
}

return [{ json: summary }, ...items];

